{
  "brand": {
    "name": "Pipelex",
    "website": "https://pipelex.com/",
    "logo": {
      "onLight": "https://pipelex.com/logo.png",
      "onDark": "https://pipelex.com/logo.png"
    },
    "webfont": { "provider": "google-fonts", "family": "Inter" }
  },
  "tokens": {
    "color": {
      "$type": "color",
      "background": {
        "$value": { "colorSpace": "srgb", "components": [0.9569, 0.9569, 0.9647], "alpha": 1, "hex": "#f4f4f6" },
        "$description": "The page canvas: the site is dark (body bg-[#0a0a0b]), so light mode is the inverted canvas.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [0.0392, 0.0392, 0.0431], "alpha": 1, "hex": "#0a0a0b" }
          }
        }
      },
      "foreground": {
        "$value": { "colorSpace": "srgb", "components": [0.0392, 0.0392, 0.0431], "alpha": 1, "hex": "#0a0a0b" },
        "$description": "Text on the canvas: the site's text-white ink, inverted for light mode.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [1, 1, 1], "alpha": 1, "hex": "#ffffff" }
          }
        }
      },
      "card": {
        "$value": { "colorSpace": "srgb", "components": [0, 0, 0], "alpha": 0.04 },
        "$description": "A raised surface: the site's bg-white/5 panels, a translucent step off the canvas; inverted to a black wash on the light canvas.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [1, 1, 1], "alpha": 0.05, "hex": "#ffffff" }
          }
        }
      },
      "card-foreground": {
        "$value": { "colorSpace": "srgb", "components": [0.0392, 0.0392, 0.0431], "alpha": 1, "hex": "#0a0a0b" },
        "$description": "Text on a card: the same ink as the canvas text.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [1, 1, 1], "alpha": 1, "hex": "#ffffff" }
          }
        }
      },
      "popover": {
        "$value": { "colorSpace": "srgb", "components": [1, 1, 1], "alpha": 1, "hex": "#ffffff" },
        "$description": "A floating surface, opaque: derived a step off the light canvas, inverted from the site's dark bg-bg-darker menus.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [0.051, 0.0431, 0.0784], "alpha": 1, "hex": "#0d0b14" }
          }
        }
      },
      "popover-foreground": {
        "$value": { "colorSpace": "srgb", "components": [0.0392, 0.0392, 0.0431], "alpha": 1, "hex": "#0a0a0b" },
        "$description": "Text on a popover: the ink.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [1, 1, 1], "alpha": 1, "hex": "#ffffff" }
          }
        }
      },
      "primary": {
        "$value": { "colorSpace": "srgb", "components": [0, 0.7333, 0.5843], "alpha": 1, "hex": "#00bb95" },
        "$description": "The accent: the site's --accent-teal (#00bb95), its run buttons and highlights; kept across modes.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [0, 0.7333, 0.5843], "alpha": 1, "hex": "#00bb95" }
          }
        }
      },
      "primary-foreground": {
        "$value": { "colorSpace": "srgb", "components": [1, 1, 1], "alpha": 1, "hex": "#ffffff" },
        "$description": "Text on the accent: white, as the site sets on its bg-accent-teal buttons.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [1, 1, 1], "alpha": 1, "hex": "#ffffff" }
          }
        }
      },
      "secondary": {
        "$value": { "colorSpace": "srgb", "components": [0, 0, 0], "alpha": 0.06 },
        "$description": "A quiet filled surface: the site's bg-white/[0.06] fills, inverted to a black wash on the light canvas.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [1, 1, 1], "alpha": 0.06, "hex": "#ffffff" }
          }
        }
      },
      "secondary-foreground": {
        "$value": { "colorSpace": "srgb", "components": [0.0392, 0.0392, 0.0431], "alpha": 1, "hex": "#0a0a0b" },
        "$description": "Text on a secondary surface: the ink.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [1, 1, 1], "alpha": 1, "hex": "#ffffff" }
          }
        }
      },
      "muted": {
        "$value": { "colorSpace": "srgb", "components": [0, 0, 0], "alpha": 0.03 },
        "$description": "A subdued fill: the site's faintest bg-white/[0.03] band, inverted for the light canvas.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [1, 1, 1], "alpha": 0.03, "hex": "#ffffff" }
          }
        }
      },
      "muted-foreground": {
        "$value": { "colorSpace": "srgb", "components": [0.3373, 0.3608, 0.4], "alpha": 1, "hex": "#565c66" },
        "$description": "Secondary text: the site's text-gray-400 (#9ca3af) hints, darkened for contrast on the light canvas.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [0.6157, 0.6392, 0.6863], "alpha": 1, "hex": "#9ca3af" }
          }
        }
      },
      "accent": {
        "$value": { "colorSpace": "srgb", "components": [0, 0.7333, 0.5843], "alpha": 0.1 },
        "$description": "A hover fill: the site's bg-accent-teal/10, a teal wash under the pointer.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [0, 0.7333, 0.5843], "alpha": 0.1 }
          }
        }
      },
      "accent-foreground": {
        "$value": { "colorSpace": "srgb", "components": [0, 0.7333, 0.5843], "alpha": 1, "hex": "#00bb95" },
        "$description": "Text on an accent fill: the teal accent, as text-accent-teal reads on its own wash.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [0, 0.7333, 0.5843], "alpha": 1, "hex": "#00bb95" }
          }
        }
      },
      "destructive": {
        "$value": { "colorSpace": "srgb", "components": [0.9569, 0.2471, 0.3686], "alpha": 1, "hex": "#f43f5e" },
        "$description": "The error colour: the site's bg-rose-500 (#f43f5e) remove and invalid marks.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [0.9569, 0.2471, 0.3686], "alpha": 1, "hex": "#f43f5e" }
          }
        }
      },
      "destructive-foreground": {
        "$value": { "colorSpace": "srgb", "components": [1, 1, 1], "alpha": 1, "hex": "#ffffff" },
        "$description": "Text on the destructive colour: white.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [1, 1, 1], "alpha": 1, "hex": "#ffffff" }
          }
        }
      },
      "border": {
        "$value": { "colorSpace": "srgb", "components": [0, 0, 0], "alpha": 0.1 },
        "$description": "The hairline: the site's border-white/10, inverted to a black hairline on the light canvas.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [1, 1, 1], "alpha": 0.1, "hex": "#ffffff" }
          }
        }
      },
      "input": {
        "$value": { "colorSpace": "srgb", "components": [0, 0, 0], "alpha": 0.06 },
        "$description": "The control surface: a step off the canvas matching the site's bg-white/10 fields, inverted for light mode.",
        "$extensions": {
          "mode": {
            "dark": { "colorSpace": "srgb", "components": [1, 1, 1], "alpha": 0.1, "hex": "#ffffff" }
          }
        }
      },
      "ring": {
        "$value": "{color.primary}",
        "$description": "The focus ring: the site's ring-accent-teal, the teal accent."
      }
    },
    "radius": {
      "$type": "dimension",
      "base": {
        "$value": { "value": 0.75, "unit": "rem" },
        "$description": "The site's controls and cards are rounded-xl (.75rem), its most frequent bounded corner."
      }
    },
    "font": {
      "$type": "fontFamily",
      "sans": {
        "$value": ["Inter", "ui-sans-serif", "system-ui", "sans-serif"],
        "$description": "The site's one typeface, Inter, loaded as a web font, with the system stack behind it."
      },
      "mono": {
        "$value": ["ui-monospace", "SFMono-Regular", "Menlo", "Monaco", "Consolas", "monospace"],
        "$description": "The site's font-mono stack for tags and numbers: ui-monospace and the system stack."
      }
    }
  }
}

